//! The help screens: `help` searches the shortcut topics with fzf, `help-topic` prints one.

use crate::error::Result;
use crate::paths::{self, cannot_read};
use crate::process::{Spawn, exec, spawn, which};
use crate::text::{py_strip, shlex_quote};
use std::io::{self, Write};
use std::path::{Path, PathBuf};

pub use crate::help_topics::TOPICS;

/// One shortcut, as the help lists it and as `help-topic` explains it. The texts are generated by
/// scripts/gen_help.py from the topics of the Python controller (src/help_topics.rs).
pub struct Topic {
    pub id: &'static str,
    /// The line fzf shows.
    pub display: &'static str,
    pub title: &'static str,
    pub text: &'static str,
}

/// What `help-topic ID` prints: the topic, or that there is none.
pub fn help_topic(id: &str) -> String {
    match TOPICS.iter().find(|topic| topic.id == id) {
        Some(topic) => format!("=== {} ===\n\n{}\n\n", topic.title, topic.text),
        None => format!("Topic '{id}' not found.\n"),
    }
}

/// `tmux-workspace help-topic ID`. This is also the preview of the fzf list.
pub fn print_topic(id: &str) {
    show(&help_topic(id));
}

/// Write to stdout. A reader that went away, such as an fzf preview that was replaced, is not an error.
fn show(text: &str) {
    let mut stdout = io::stdout().lock();
    let _ = stdout.write_all(text.as_bytes());
    let _ = stdout.flush();
}

/// The offline manual that the installer writes.
fn guide_path() -> PathBuf {
    paths::home().join(".config/tmux/WORKSPACE_GUIDE.md")
}

fn on_a_terminal() -> bool {
    // SAFETY: `isatty` only inspects file descriptors 0 and 1.
    unsafe { libc::isatty(0) == 1 && libc::isatty(1) == 1 }
}

/// The command that shows a file in the pager.
fn page(path: &str) -> Vec<String> {
    ["less", "-R", "--", path].map(String::from).to_vec()
}

/// `tmux-workspace help`: fuzzy-search the topics, and read the one chosen. Without fzf or without
/// a terminal, show the manual if there is one, else every topic.
pub fn help_interactive() -> Result<()> {
    let guide = guide_path();
    let terminal = on_a_terminal();
    if which("fzf").is_none() || !terminal {
        if guide.is_file() && which("less").is_some() && terminal {
            return Err(exec(&page(&guide.to_string_lossy())));
        }
        if guide.is_file() {
            let manual = std::fs::read_to_string(&guide).map_err(|e| cannot_read(&guide, e))?;
            // Python reads text with universal newlines, and print adds one.
            show(&format!(
                "{}\n",
                manual.replace("\r\n", "\n").replace('\r', "\n")
            ));
        } else {
            show(&TOPICS.iter().map(|t| help_topic(t.id)).collect::<String>());
        }
        return Ok(());
    }
    search(&guide)
}

/// The fzf command line: ids are hidden, and the preview is this program's `help-topic`.
fn fzf() -> Vec<String> {
    [
        "fzf",
        "--delimiter=\t",
        "--with-nth=2",
        &format!(
            "--preview={} help-topic {{1}}",
            shlex_quote(&paths::self_path())
        ),
        "--preview-window=right:58%:wrap",
        "--header=Type to fuzzy search commands | Enter: view full help | Esc: quit",
        "--prompt=Help > ",
        "--info=inline",
        "--height=100%",
        "--layout=reverse",
        "--border=rounded",
    ]
    .map(String::from)
    .to_vec()
}

/// Choose a topic and read it, until fzf is cancelled.
fn search(guide: &Path) -> Result<()> {
    let list = TOPICS
        .iter()
        .map(|topic| format!("{}\t{}", topic.id, topic.display))
        .collect::<Vec<_>>()
        .join("\n");
    loop {
        let chosen = spawn(&Spawn {
            argv: fzf(),
            stdin: Some(list.clone()),
            ..Spawn::default()
        })?;
        let picked = py_strip(&chosen.stdout);
        if chosen.status != 0 || picked.is_empty() {
            return Ok(());
        }
        let id = picked.split('\t').next().unwrap_or_default();
        if id == "topic-guide" {
            if guide.is_file() && which("less").is_some() {
                spawn(&Spawn {
                    argv: page(&guide.to_string_lossy()),
                    inherit_stdio: true,
                    ..Spawn::default()
                })?;
            }
        } else if let Some(topic) = TOPICS.iter().find(|topic| topic.id == id) {
            read_topic(topic)?;
        }
    }
}

/// Show a topic in the pager, or print it and wait for Enter.
fn read_topic(topic: &Topic) -> Result<()> {
    let body = format!(
        "=== {} ===\n\n{}\n\n[Press 'q' or 'Enter' to return to search...]",
        topic.title, topic.text
    );
    if which("less").is_some() {
        spawn(&Spawn {
            argv: ["less", "-R", "-P", " Press q to return to search..."]
                .map(String::from)
                .to_vec(),
            stdin: Some(body),
            inherit_stdio: true,
            ..Spawn::default()
        })?;
    } else {
        show(&format!("{body}\n"));
        // Enter, the end of input or an error all go back to the search.
        let _ = io::stdin().read_line(&mut String::new());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn there_are_34_topics_with_distinct_ids() {
        assert_eq!(TOPICS.len(), 34);
        let ids: HashSet<_> = TOPICS.iter().map(|t| t.id).collect();
        assert_eq!(ids.len(), 34);
        for topic in TOPICS {
            assert!(!topic.display.is_empty() && !topic.title.is_empty() && !topic.text.is_empty());
            assert!(!topic.id.contains('\t') && !topic.display.contains(['\t', '\n']));
        }
    }

    #[test]
    fn a_topic_is_its_title_and_text_between_blank_lines() {
        let topic = TOPICS.iter().find(|t| t.id == "topic-guide").unwrap();
        assert_eq!(
            help_topic("topic-guide"),
            format!(
                "=== Full Offline Reference Manual ===\n\n{}\n\n",
                topic.text
            )
        );
        assert!(topic.text.starts_with("The complete 12-section manual"));
    }

    #[test]
    fn an_unknown_topic_is_named_back() {
        assert_eq!(help_topic("nope"), "Topic 'nope' not found.\n");
        assert_eq!(help_topic(""), "Topic '' not found.\n");
    }

    #[test]
    fn the_preview_command_quotes_the_program() {
        let fzf = fzf();
        assert_eq!(fzf[0], "fzf");
        assert_eq!(fzf[1], "--delimiter=\t");
        let preview = fzf[3].strip_prefix("--preview=").unwrap();
        assert!(preview.ends_with(" help-topic {1}"), "{preview}");
    }
}
